def count(msgs):
    return sum(len(enc.encode(m["content"])) for m in msgs)

def prune(history: list) -> list:
    if count(history) <= LIMIT:
        return history
    old, recent = history[:-KEEP_RECENT], history[-KEEP_RECENT:]
    summary = llm("Summarize the decisions, facts and open tasks. Be brief.\n\n"
                  + "\n".join(f'{m["role"]}: {m["content"]}' for m in old))
    return [{"role": "user", "content": f"Summary of earlier conversation: {summary}"},
            {"role": "assistant", "content": "Noted."}] + recent

